"use client";

import { cn } from "@/lib/utils";
import { CanvasStage } from "@/registry/ivan/components/canvas-stage/canvas-stage";

import { orbitDustDefaults } from "./orbit-dust-material";
import { OrbitDustScene } from "./orbit-dust-scene";
import type { OrbitDustSceneProps } from "./orbit-dust-scene";

export interface OrbitDustProps extends OrbitDustSceneProps {
  className?: string;
  label?: string;
}

const defaultLabel = "A ring of dust orbiting a dark core";

const fallbackRing = (ink: string, paper: string) =>
  `radial-gradient(ellipse 18% 18% at 50% 50%, ${ink} 98%, transparent 100%), radial-gradient(ellipse 46% 15% at 50% 50%, transparent 52%, color-mix(in srgb, ${paper} 55%, transparent) 60%, color-mix(in srgb, ${paper} 25%, transparent) 82%, transparent 100%)`;

export const OrbitDust = ({
  className,
  label = defaultLabel,
  ink = orbitDustDefaults.ink,
  paper = orbitDustDefaults.paper,
  paused = orbitDustDefaults.paused,
  ...sceneProps
}: OrbitDustProps) => (
  <CanvasStage
    className={cn("aspect-video", className)}
    fallback={
      <div
        aria-hidden
        className="absolute inset-0"
        style={{ backgroundImage: fallbackRing(ink, paper) }}
      />
    }
    ground={ink}
    label={label}
    paused={paused}
  >
    {(isAnimating) => (
      <OrbitDustScene
        {...sceneProps}
        ink={ink}
        paper={paper}
        paused={!isAnimating}
      />
    )}
  </CanvasStage>
);

"use client";

import { useFrame, useThree } from "@react-three/fiber";
import type { ThreeEvent } from "@react-three/fiber";
import { useEffect, useLayoutEffect, useMemo, useRef } from "react";
import {
  MathUtils,
  PerspectiveCamera,
  PlaneGeometry,
  SphereGeometry,
  Vector3,
} from "three";
import type { Group } from "three";

import { OrbitCoreMaterial } from "./orbit-core-material";
import {
  OrbitDustMaterial,
  createDustGeometry,
  dustOpacityFor,
  normalizeDustCount,
  orbitDustDefaults,
} from "./orbit-dust-material";

export interface OrbitDustSceneProps {
  count?: number;
  radius?: number;
  thickness?: number;
  turbulence?: number;
  speed?: number;
  ink?: string;
  paper?: string;
  paused?: boolean;
}

const cameraFov = 30;
const cameraElevation = 0.3;
const ringRoll = -0.16;
const frameRadius = 2;
const coreShare = 0.36;
const wellEase = 4;
const maxStep = 0.05;

const fitDustCamera = (
  camera: PerspectiveCamera,
  width: number,
  height: number
) => {
  const aspect = width / Math.max(height, 1);
  const halfTangent = Math.tan(MathUtils.degToRad(cameraFov / 2));
  const distance = Math.max(
    (frameRadius * 1.12) / (halfTangent * aspect),
    (frameRadius * 0.62) / halfTangent
  );
  camera.aspect = aspect;
  camera.position.set(
    0,
    Math.sin(cameraElevation) * distance,
    Math.cos(cameraElevation) * distance
  );
  camera.lookAt(0, 0, 0);
  camera.updateProjectionMatrix();
  return distance;
};

class DustRig {
  readonly material = new OrbitDustMaterial();
  readonly core = new SphereGeometry(1, 48, 32);
  readonly coreMaterial = new OrbitCoreMaterial();
  readonly hitPlane = new PlaneGeometry(1, 1);
  private readonly wellTarget = new Vector3();
  private wellStrengthTarget = 0;
  private elapsed = 0;
  private isLitDust = true;

  applyTones(ink: string, paper: string, count: number) {
    this.isLitDust = this.material.setTones(ink, paper);
    this.coreMaterial.setTones(ink, paper);
    this.material.uniforms.uOpacity.value = dustOpacityFor(
      count,
      this.isLitDust
    );
  }

  applyRingGeometry(radius: number, thickness: number, turbulence: number) {
    const { uniforms } = this.material;
    uniforms.uRadius.value = radius;
    uniforms.uThickness.value = thickness;
    uniforms.uTurbulence.value = turbulence;
  }

  applyViewport(distance: number, height: number, pixelRatio: number) {
    const { uniforms } = this.material;
    uniforms.uCameraDistance.value = distance;
    uniforms.uViewportHeight.value = height;
    uniforms.uPixelRatio.value = pixelRatio;
  }

  aim(point: Vector3 | null) {
    if (point) {
      this.wellTarget.copy(point);
      this.wellStrengthTarget = 1;
    } else {
      this.wellStrengthTarget = 0;
    }
  }

  advance(delta: number, speed: number, paused: boolean) {
    const { uniforms } = this.material;
    const step = Math.min(delta, maxStep);
    if (paused) {
      uniforms.uWell.value.copy(this.wellTarget);
      uniforms.uWellStrength.value = this.wellStrengthTarget;
      return;
    }
    this.elapsed += step * speed;
    const blend = 1 - Math.exp(-wellEase * step);
    uniforms.uWell.value.lerp(this.wellTarget, blend);
    uniforms.uWellStrength.value = MathUtils.lerp(
      uniforms.uWellStrength.value,
      this.wellStrengthTarget,
      blend
    );
    uniforms.uTime.value = this.elapsed;
  }

  dispose() {
    this.material.dispose();
    this.core.dispose();
    this.coreMaterial.dispose();
    this.hitPlane.dispose();
  }
}

const DustCamera = ({ rig }: { rig: DustRig }) => {
  const set = useThree((state) => state.set);
  const get = useThree((state) => state.get);
  const invalidate = useThree((state) => state.invalidate);
  const width = useThree((state) => state.size.width);
  const height = useThree((state) => state.size.height);
  const pixelRatio = useThree((state) => state.viewport.dpr);
  const camera = useMemo(
    () => new PerspectiveCamera(cameraFov, 1, 0.1, 100),
    []
  );

  useLayoutEffect(() => {
    rig.applyViewport(fitDustCamera(camera, width, height), height, pixelRatio);
    invalidate();
  }, [camera, height, invalidate, pixelRatio, rig, width]);

  useLayoutEffect(() => {
    const previous = get().camera;
    set({ camera });
    return () => set({ camera: previous });
  }, [camera, get, set]);

  return null;
};

export const OrbitDustScene = ({
  count,
  radius = orbitDustDefaults.radius,
  thickness = orbitDustDefaults.thickness,
  turbulence = orbitDustDefaults.turbulence,
  speed = orbitDustDefaults.speed,
  ink = orbitDustDefaults.ink,
  paper = orbitDustDefaults.paper,
  paused = orbitDustDefaults.paused,
}: OrbitDustSceneProps) => {
  const invalidate = useThree((state) => state.invalidate);
  const ring = useRef<Group>(null);
  const rig = useMemo(() => new DustRig(), []);
  const particleCount = useMemo(() => normalizeDustCount(count), [count]);
  const geometry = useMemo(
    () => createDustGeometry(particleCount),
    [particleCount]
  );

  useEffect(() => () => rig.dispose(), [rig]);
  useEffect(() => () => geometry.dispose(), [geometry]);

  useEffect(() => {
    rig.applyTones(ink, paper, particleCount);
    invalidate();
  }, [ink, invalidate, paper, particleCount, rig]);

  useEffect(() => {
    rig.applyRingGeometry(radius, thickness, turbulence);
    invalidate();
  }, [invalidate, radius, rig, thickness, turbulence]);

  useFrame((_, delta) => {
    rig.advance(delta, speed, paused);
  });

  const handleMove = (event: ThreeEvent<PointerEvent>) => {
    const group = ring.current;
    if (!group) {
      return;
    }
    rig.aim(group.worldToLocal(event.point.clone()));
    invalidate();
  };

  const handleLeave = () => {
    rig.aim(null);
    invalidate();
  };

  return (
    <>
      <DustCamera rig={rig} />
      <group ref={ring} rotation={[0, 0, ringRoll]}>
        <points
          frustumCulled={false}
          geometry={geometry}
          material={rig.material}
        />
        <mesh
          geometry={rig.core}
          material={rig.coreMaterial}
          scale={radius * coreShare}
        />
        <mesh
          geometry={rig.hitPlane}
          onPointerLeave={handleLeave}
          onPointerMove={handleMove}
          rotation={[-Math.PI / 2, 0, 0]}
          scale={radius * 6}
          visible={false}
        />
      </group>
    </>
  );
};

import {
  AdditiveBlending,
  BufferAttribute,
  BufferGeometry,
  Color,
  NormalBlending,
  ShaderMaterial,
  Vector3,
} from "three";
import type { IUniform } from "three";

export const orbitDustDefaults = {
  ink: "#0B0B0C",
  paper: "#EDECE8",
  paused: false,
  radius: 1.6,
  speed: 1,
  thickness: 0.06,
  turbulence: 0.5,
} as const;

export const orbitDustLimits = {
  maxCount: 200_000,
  minCount: 50_000,
} as const;

export interface OrbitDustUniforms {
  [uniform: string]: IUniform;
  uTime: IUniform<number>;
  uRadius: IUniform<number>;
  uThickness: IUniform<number>;
  uTurbulence: IUniform<number>;
  uSize: IUniform<number>;
  uPixelRatio: IUniform<number>;
  uViewportHeight: IUniform<number>;
  uCameraDistance: IUniform<number>;
  uOpacity: IUniform<number>;
  uWell: IUniform<Vector3>;
  uWellStrength: IUniform<number>;
  uPaper: IUniform<Color>;
  uShade: IUniform<Color>;
}

const innerEdge = 0.48;
const ringGaps = [
  { at: 0.66, width: 0.018 },
  { at: 0.83, width: 0.03 },
] as const;

const vertexShader = `
uniform float uTime;
uniform float uRadius;
uniform float uThickness;
uniform float uTurbulence;
uniform float uSize;
uniform float uPixelRatio;
uniform float uViewportHeight;
uniform float uCameraDistance;
uniform vec3 uWell;
uniform float uWellStrength;

attribute float aSeed;

varying float vAlpha;
varying float vTone;

float hash13(vec3 p) {
  p = fract(p * 0.1031);
  p += dot(p, p.zyx + 31.32);
  return fract((p.x + p.y) * p.z);
}

vec4 noised(vec3 x) {
  vec3 i = floor(x);
  vec3 w = fract(x);
  vec3 u = w * w * (3.0 - 2.0 * w);
  vec3 du = 6.0 * w * (1.0 - w);
  float a = hash13(i);
  float b = hash13(i + vec3(1.0, 0.0, 0.0));
  float c = hash13(i + vec3(0.0, 1.0, 0.0));
  float d = hash13(i + vec3(1.0, 1.0, 0.0));
  float e = hash13(i + vec3(0.0, 0.0, 1.0));
  float f = hash13(i + vec3(1.0, 0.0, 1.0));
  float g = hash13(i + vec3(0.0, 1.0, 1.0));
  float h = hash13(i + vec3(1.0, 1.0, 1.0));
  float k1 = b - a;
  float k2 = c - a;
  float k3 = e - a;
  float k4 = a - b - c + d;
  float k5 = a - c - e + g;
  float k6 = a - b - e + f;
  float k7 = -a + b + c - d + e - f - g + h;
  float value = a + k1 * u.x + k2 * u.y + k3 * u.z + k4 * u.x * u.y + k5 * u.y * u.z + k6 * u.z * u.x + k7 * u.x * u.y * u.z;
  vec3 gradient = du * vec3(
    k1 + k4 * u.y + k6 * u.z + k7 * u.y * u.z,
    k2 + k5 * u.z + k4 * u.x + k7 * u.z * u.x,
    k3 + k6 * u.x + k5 * u.y + k7 * u.x * u.y
  );
  return vec4(value, gradient);
}

vec3 curlNoise(vec3 p) {
  vec3 dx = noised(p).yzw;
  vec3 dy = noised(p + vec3(31.4, 17.1, 5.3)).yzw;
  vec3 dz = noised(p + vec3(-11.7, 43.2, 27.9)).yzw;
  return vec3(dz.y - dy.z, dx.z - dz.x, dy.x - dx.y);
}

void main() {
  float band = position.x;
  float radius = band * uRadius;
  float angularVelocity = 0.42 / pow(max(band, 0.2), 1.5);
  float angle = position.y + uTime * angularVelocity;
  vec3 orbit = vec3(cos(angle) * radius, position.z * uThickness, sin(angle) * radius);

  vec3 flowPoint = orbit * (1.4 / uRadius) + vec3(0.0, uTime * 0.05, uTime * 0.03);
  vec3 swirl = curlNoise(flowPoint) * uTurbulence * 0.05 * uRadius * (0.35 + 0.65 * aSeed);
  orbit += swirl * vec3(1.0, 0.45, 1.0);

  vec3 toWell = uWell - orbit;
  toWell.y = 0.0;
  float reach = 0.32 * uRadius;
  float pull = uWellStrength * exp(-dot(toWell, toWell) / (reach * reach));
  orbit.xz += toWell.xz * pull * 0.55;
  orbit.y -= pull * reach * 0.6 * (0.6 + aSeed);

  vec4 viewPosition = modelViewMatrix * vec4(orbit, 1.0);
  float depth = max(-viewPosition.z, 0.001);
  float spriteSize = uSize * (0.55 + aSeed * 0.9) * uPixelRatio * uViewportHeight * projectionMatrix[1][1] * 0.5 / depth;
  float clampedSize = clamp(spriteSize, 1.0, 42.0);
  gl_PointSize = clampedSize;
  gl_Position = projectionMatrix * viewPosition;

  float depthFade = smoothstep(uCameraDistance + uRadius * 1.15, uCameraDistance - uRadius * 1.15, depth);
  float innerGlow = 1.0 - smoothstep(0.48, 1.0, band);
  float twinkle = 0.78 + 0.22 * sin(uTime * (0.6 + aSeed * 2.4) + aSeed * 61.0);
  float subPixel = min(spriteSize / clampedSize, 1.0);
  vAlpha = (0.35 + 0.65 * depthFade) * (0.55 + 0.45 * innerGlow) * twinkle * subPixel * (1.0 + pull * 1.5);
  vTone = step(0.7, fract(aSeed * 7.13)) * (1.0 - innerGlow * 0.5);
}
`;

const fragmentShader = `
uniform float uOpacity;
uniform vec3 uPaper;
uniform vec3 uShade;

varying float vAlpha;
varying float vTone;

void main() {
  float distanceToCenter = length(gl_PointCoord - 0.5);
  float sprite = pow(smoothstep(0.5, 0.0, distanceToCenter), 1.6);
  if (sprite < 0.004) discard;
  gl_FragColor = vec4(mix(uPaper, uShade, vTone), sprite * vAlpha * uOpacity);
  #include <colorspace_fragment>
}
`;

const createUniforms = (): OrbitDustUniforms => ({
  uCameraDistance: { value: 6 },
  uOpacity: { value: 0.5 },
  uPaper: { value: new Color(orbitDustDefaults.paper) },
  uPixelRatio: { value: 1 },
  uRadius: { value: orbitDustDefaults.radius },
  uShade: { value: new Color(orbitDustDefaults.paper) },
  uSize: { value: 0.012 },
  uThickness: { value: orbitDustDefaults.thickness },
  uTime: { value: 0 },
  uTurbulence: { value: orbitDustDefaults.turbulence },
  uViewportHeight: { value: 600 },
  uWell: { value: new Vector3() },
  uWellStrength: { value: 0 },
});

const luminance = ({ r, g, b }: Color) => 0.2126 * r + 0.7152 * g + 0.0722 * b;

export class OrbitDustMaterial extends ShaderMaterial {
  declare uniforms: OrbitDustUniforms;

  constructor() {
    super({
      blending: AdditiveBlending,
      depthWrite: false,
      fragmentShader,
      toneMapped: false,
      transparent: true,
      uniforms: createUniforms(),
      vertexShader,
    });
  }

  setTones(ink: string, paper: string) {
    const ground = new Color(ink);
    const dust = new Color(paper);
    const isLitDust = luminance(dust) >= luminance(ground);
    this.uniforms.uPaper.value.copy(dust);
    this.uniforms.uShade.value.copy(ground).lerp(dust, 0.45);
    this.blending = isLitDust ? AdditiveBlending : NormalBlending;
    return isLitDust;
  }
}

const lcgModulus = 4_294_967_296;

const createRandom = (seed: number) => {
  let state = Math.abs(Math.floor(seed)) % lcgModulus;
  return () => {
    state = (1_664_525 * state + 1_013_904_223) % lcgModulus;
    return state / lcgModulus;
  };
};

const bandDensity = (band: number) => {
  let density =
    0.35 +
    0.65 * Math.sin(Math.PI * ((band - innerEdge) / (1 - innerEdge)) ** 0.7);
  for (const gap of ringGaps) {
    const offset = (band - gap.at) / gap.width;
    density *= 1 - 0.92 * Math.exp(-offset * offset);
  }
  return density;
};

const gaussian = (random: () => number) =>
  Math.sqrt(-2 * Math.log(Math.max(random(), 1e-6))) *
  Math.cos(2 * Math.PI * random());

export interface DustParticle {
  band: number;
  angle: number;
  height: number;
  seed: number;
}

export const sampleDust = (count: number, seed = 7) => {
  const random = createRandom(seed);
  const particles: DustParticle[] = [];
  while (particles.length < count) {
    const band = innerEdge + (1 - innerEdge) * random();
    if (random() > bandDensity(band)) {
      continue;
    }
    const flare = 0.35 + 0.65 * ((band - innerEdge) / (1 - innerEdge));
    particles.push({
      angle: random() * Math.PI * 2,
      band,
      height: gaussian(random) * flare,
      seed: random(),
    });
  }
  return particles;
};

export const createDustGeometry = (count: number) => {
  const particles = sampleDust(count);
  const orbits = new Float32Array(count * 3);
  const seeds = new Float32Array(count);
  for (const [index, particle] of particles.entries()) {
    orbits[index * 3] = particle.band;
    orbits[index * 3 + 1] = particle.angle;
    orbits[index * 3 + 2] = particle.height;
    seeds[index] = particle.seed;
  }
  const geometry = new BufferGeometry();
  geometry.setAttribute("position", new BufferAttribute(orbits, 3));
  geometry.setAttribute("aSeed", new BufferAttribute(seeds, 1));
  return geometry;
};

const clampCount = (count: number) =>
  Math.round(
    Math.min(
      Math.max(count, orbitDustLimits.minCount),
      orbitDustLimits.maxCount
    )
  );

export const resolveDustCount = () => {
  if (typeof window === "undefined") {
    return 80_000;
  }
  const cores = navigator.hardwareConcurrency || 4;
  const pixelRatio = window.devicePixelRatio || 1;
  const isCoarse = window.matchMedia("(pointer: coarse)").matches;
  let count = 70_000;
  if (cores >= 12) {
    count = 200_000;
  } else if (cores >= 8) {
    count = 150_000;
  } else if (cores >= 6) {
    count = 110_000;
  }
  if (pixelRatio > 2.5) {
    count *= 0.5;
  } else if (pixelRatio > 2) {
    count *= 0.7;
  }
  if (isCoarse) {
    count *= 0.6;
  }
  return clampCount(count);
};

export const normalizeDustCount = (count: number | undefined) =>
  count === undefined ? resolveDustCount() : clampCount(count);

export const dustOpacityFor = (count: number, isLitDust: boolean) =>
  (isLitDust ? 0.55 : 0.45) * Math.sqrt(120_000 / count);

import { Color, ShaderMaterial } from "three";
import type { IUniform } from "three";

import { orbitDustDefaults } from "./orbit-dust-material";

const coreVertexShader = `
varying vec3 vNormal;
varying vec3 vView;

void main() {
  vec4 viewPosition = modelViewMatrix * vec4(position, 1.0);
  vNormal = normalize(normalMatrix * normal);
  vView = normalize(-viewPosition.xyz);
  gl_Position = projectionMatrix * viewPosition;
}
`;

const coreFragmentShader = `
uniform vec3 uInk;
uniform vec3 uPaper;

varying vec3 vNormal;
varying vec3 vView;

void main() {
  float limb = 1.0 - max(dot(normalize(vNormal), normalize(vView)), 0.0);
  float rim = pow(limb, 5.0) * 0.55;
  gl_FragColor = vec4(mix(uInk, uPaper, rim), 1.0);
  #include <colorspace_fragment>
}
`;

export class OrbitCoreMaterial extends ShaderMaterial {
  declare uniforms: {
    [uniform: string]: IUniform;
    uInk: IUniform<Color>;
    uPaper: IUniform<Color>;
  };

  constructor() {
    super({
      fragmentShader: coreFragmentShader,
      toneMapped: false,
      uniforms: {
        uInk: { value: new Color(orbitDustDefaults.ink) },
        uPaper: { value: new Color(orbitDustDefaults.paper) },
      },
      vertexShader: coreVertexShader,
    });
  }

  setTones(ink: string, paper: string) {
    this.uniforms.uInk.value.set(ink);
    this.uniforms.uPaper.value.set(paper);
  }
}

"use client";

import { Canvas } from "@react-three/fiber";
import { useRef } from "react";
import type { ComponentProps, ReactNode } from "react";

import { cn } from "@/lib/utils";
import { useInView } from "@/registry/ivan/hooks/use-in-view";
import { usePrefersReducedMotion } from "@/registry/ivan/hooks/use-prefers-reduced-motion";
import { useWebGLSupport } from "@/registry/ivan/hooks/use-webgl-support";

export interface CanvasStageProps {
  ground: string;
  label: string;
  paused: boolean;
  fallback: ReactNode;
  antialias?: boolean;
  camera?: ComponentProps<typeof Canvas>["camera"];
  className?: string;
  children: (isAnimating: boolean) => ReactNode;
}

interface ImageFallbackProps {
  src: string;
  focus: { x: number; y: number };
}

export const ImageFallback = ({ src, focus }: ImageFallbackProps) => (
  <div
    aria-hidden
    className="absolute inset-0 grayscale"
    style={{
      backgroundImage: `url(${JSON.stringify(src)})`,
      backgroundPosition: `${focus.x * 100}% ${focus.y * 100}%`,
      backgroundSize: "cover",
    }}
  />
);

export const CanvasStage = ({
  ground,
  label,
  paused,
  fallback,
  antialias = false,
  camera,
  className,
  children,
}: CanvasStageProps) => {
  const frame = useRef<HTMLElement>(null);
  const hasWebGL = useWebGLSupport();
  const isInView = useInView(frame);
  const prefersReducedMotion = usePrefersReducedMotion();
  const isAnimating = isInView && !prefersReducedMotion && !paused;

  return (
    <figure
      aria-label={label}
      className={cn(
        "relative m-0 aspect-4/3 w-full overflow-hidden",
        className
      )}
      ref={frame}
      style={{ backgroundColor: ground }}
    >
      {hasWebGL ? (
        <Canvas
          aria-hidden
          camera={camera}
          dpr={[1, 1.75]}
          frameloop={isAnimating ? "always" : "demand"}
          gl={{
            alpha: true,
            antialias,
            powerPreference: "high-performance",
          }}
        >
          {children(isAnimating)}
        </Canvas>
      ) : (
        fallback
      )}
    </figure>
  );
};

"use client";

import { useSyncExternalStore } from "react";

const reducedMotionQuery = "(prefers-reduced-motion: reduce)";

const subscribe = (onChange: () => void) => {
  const mediaQuery = window.matchMedia(reducedMotionQuery);
  mediaQuery.addEventListener("change", onChange);
  return () => mediaQuery.removeEventListener("change", onChange);
};

const getSnapshot = () => window.matchMedia(reducedMotionQuery).matches;

const getServerSnapshot = () => false;

export const usePrefersReducedMotion = () =>
  useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);

"use client";

import { useSyncExternalStore } from "react";

let cachedSupport: boolean | null = null;

const detectWebGL = () => {
  if (cachedSupport !== null) {
    return cachedSupport;
  }
  try {
    const probe = document.createElement("canvas");
    const context = probe.getContext("webgl2") ?? probe.getContext("webgl");
    context?.getExtension("WEBGL_lose_context")?.loseContext();
    cachedSupport = context !== null;
  } catch {
    cachedSupport = false;
  }
  return cachedSupport;
};

const subscribe = (onChange: () => void) => {
  window.addEventListener("pageshow", onChange);
  return () => window.removeEventListener("pageshow", onChange);
};

const getServerSnapshot = () => true;

export const useWebGLSupport = () =>
  useSyncExternalStore(subscribe, detectWebGL, getServerSnapshot);

"use client";

import { useEffect, useState } from "react";
import type { RefObject } from "react";

export const useInView = (
  target: RefObject<Element | null>,
  rootMargin = "10% 0px"
) => {
  const [isInView, setIsInView] = useState(false);

  useEffect(() => {
    const element = target.current;
    if (!element) {
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => setIsInView(entry?.isIntersecting ?? false),
      { rootMargin }
    );
    observer.observe(element);
    return () => observer.disconnect();
  }, [rootMargin, target]);

  return isInView;
};
